import Foundation

/// Value kinds for switches whose readers parse only part of the boolean vocabulary.
/// Each accepts exactly the words that behave as written, so `on` is rejected where the
/// reader would treat it as off, and `no` where the reader would treat it as on.
extension MereRunEnvironmentValueKind {
    /// Reader enables on `1`, `true`, or `yes`; every other value is off.
    static let boolOnOnlyOneTrueYes = choice(["0", "1", "false", "no", "off", "true", "yes"])
    /// Reader enables on `1`, `true`, or `on`; every other value is off.
    static let boolOnOnlyOneTrueOn = choice(["0", "1", "false", "no", "off", "on", "true"])
    /// Reader disables on `0`, `false`, or `off`; every other value is on.
    static let boolOffOnlyZeroFalseOff = choice(["0", "1", "false", "off", "on", "true", "yes"])
    /// `LagunaAccelerationPolicy.parseLadderStride`: `off`/`0`, or a stride from 1 through 40.
    static let lagunaAsyncLadderStride = choice(["off"] + (0...40).map(String.init))
}

